import { FormEvent, useState } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxToast } from '@jinx-ui/react';

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email);
  const showError = touched && !isEmailValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isEmailValid) return;
    setSubmitted(true);
  };

  return (
    <div style={{ maxWidth: 420, display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3, 12px)' }}>
      {submitted && (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`Приглашение на ${email} успешно создано`}
          onClose={() => setSubmitted(false)}
        />
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3, 12px)' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          helperText="На этот адрес придёт приглашение в команду"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          errorText={showError ? 'Введите похожий на настоящий email-адрес' : undefined}
        />

        <JxSelect
          label="Роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление о приглашении"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={touched && !isEmailValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

